structureCode.svelte:
{#if isLoading}
  <SkeletonRegion label="Carregando lista" class="nds-stack">
    <Skeleton data-shape="avatar" />
    <Skeleton data-shape="text" data-width="3-4" />
  </SkeletonRegion>
