structureCode.vanilla:
const region = createSkeletonRegion({
  label: 'Carregando lista',
  class: 'nds-stack',
  children: [
    createSkeleton({ shape: 'avatar' }),
    createSkeleton({ shape: 'text', width: '3-4' }),
  ],
});
container.append(region);

// Quando o conteúdo chega, a região inteira sai.
region.replaceWith(list);

structureCode.angular:
@if (isLoading) {
  <div ndsSkeletonRegion label="Carregando lista" class="nds-stack">
    <div ndsSkeleton data-shape="avatar"></div>
    <div ndsSkeleton data-shape="text" data-width="3-4"></div>
  </div>
} @else {
  <ul><!-- itens reais --></ul>
}

extensibilityCode.vanilla:
// Forma e dimensão por atributo — a folha de estilo continua dona das medidas
createSkeleton({ shape: 'avatar', size: 'lg' });
createSkeleton({ shape: 'text', width: '3-4' });
createSkeleton({ shape: 'fill' });

customizationCode.web:
/* Placeholder mais marcado — a superfície continua sendo a primária */
.nds-skeleton {
  background-color: hsl(var(--primary) / 0.2);
}

/* Pulso mais curto — pelo token, que o movimento reduzido continua alcançando */
.nds-skeleton {
  --duration-cycle: 1s;
}

